mapper.select:
SELECT * FROM schema_common.risk_weight_config

    AND status = #{status}

ORDER BY created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE schema_common.risk_weight_config
config_name = #{configName}, supply_chain_weight = #{supplyChainWeight}, transaction_weight = #{transactionWeight}, material_weight = #{materialWeight}, status = #{status}, checker_id = #{checkerId}, checked_at = #{checkedAt}, reject_reason = #{rejectReason}, updated_at = NOW(),
WHERE id = #{id}

UPDATE schema_common.material_checklist_template
business_type = #{businessType}, required_materials = CAST(#{requiredMaterials, typeHandler=com.scfs.common.mybatis.JsonListTypeHandler} AS jsonb), version = #{version}, status = #{status}, checker_id = #{checkerId}, checked_at = #{checkedAt}, reject_reason = #{rejectReason}, updated_at = NOW(),
WHERE id = #{id}
